UPDATE `quest_template` SET `LogTitle`='Divine Grace', `QuestDescription`='Time''s come for you to head to Stormwind, $n. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin'' really good or really bad for the High Priestess to want you there personally, but I''m guessin'' you''ve only done well for yourself and it''s a good thing that she wants to speak to ya.\n\nBut don''t waste too much time ''round here. I''d head there as soon as you can.', `LogDescription`='Speak to High Priestess Laurena in Stormwind.', `AreaDescription`='', `QuestCompletionLog`='', `Flags`=2097160, `FlagsEx`=0, `AllowableRaces`=1, `RewardXPDifficulty`=2, `RewardXPMultiplier`=1.0, `RewardNextQuest`=0, `StartItem`=0, `RewardSpell`=1277387, `TimeAllowed`=0, `VerifiedBuild`=70862, `QuestSortID`=-262, `RewardItem1`=0, `RewardAmount1`=0, `RewardItem2`=0, `RewardAmount2`=0, `RewardItem3`=0, `RewardAmount3`=0, `RewardItem4`=0, `RewardAmount4`=0, `RewardChoiceItemID1`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `RewardFactionID1`=0, `RewardFactionValue1`=0, `RewardFactionOverride1`=0, `RewardFactionID2`=0, `RewardFactionValue2`=0, `RewardFactionOverride2`=0, `RewardFactionID3`=0, `RewardFactionValue3`=0, `RewardFactionOverride3`=0, `RewardFactionID4`=0, `RewardFactionValue4`=0, `RewardFactionOverride4`=0, `RewardFactionID5`=0, `RewardFactionValue5`=0, `RewardFactionOverride5`=0 WHERE `ID`=94776 AND `VerifiedBuild`=-1;
