-- 94777 Divine Grace (live record, 1 player(s))
UPDATE `quest_template` SET `LogTitle`='Divine Grace', `QuestDescription`='Just a short time ago, one of your priests was here looking for you, $r. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn''t take too long in making my way there if I were you.\n\nElune be with you, good $r.', `LogDescription`='Speak to High Priestess Laurena in Stormwind.', `AreaDescription`='', `QuestCompletionLog`='', `Flags`=2097160, `FlagsEx`=0, `AllowableRaces`=1, `RewardXPDifficulty`=2, `RewardXPMultiplier`=1.0, `RewardNextQuest`=0, `StartItem`=0, `RewardSpell`=1277387, `TimeAllowed`=0, `VerifiedBuild`=70862, `QuestSortID`=-262, `RewardItem1`=0, `RewardAmount1`=0, `RewardItem2`=0, `RewardAmount2`=0, `RewardItem3`=0, `RewardAmount3`=0, `RewardItem4`=0, `RewardAmount4`=0, `RewardChoiceItemID1`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `RewardFactionID1`=0, `RewardFactionValue1`=0, `RewardFactionOverride1`=0, `RewardFactionID2`=0, `RewardFactionValue2`=0, `RewardFactionOverride2`=0, `RewardFactionID3`=0, `RewardFactionValue3`=0, `RewardFactionOverride3`=0, `RewardFactionID4`=0, `RewardFactionValue4`=0, `RewardFactionOverride4`=0, `RewardFactionID5`=0, `RewardFactionValue5`=0, `RewardFactionOverride5`=0 WHERE `ID`=94777 AND `VerifiedBuild`=-1;
