UPDATE `quest_template` SET `LogTitle`='Contingency Plan', `QuestDescription`='Your race is so very clever, $n. We are proud to call you allies. And as each day''s sun sets, you and your kin grow closer to reclaiming your city, but with the burden of keeping your families safe in exile. That yearning for home must weigh heavily on you.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priestess Mims in the Mystic Ward. I would not keep her waiting. May Elune guide your travels.', `LogDescription`='Speak to High Priestess Mims in Ironforge.', `AreaDescription`='', `QuestCompletionLog`='', `Flags`=2097160, `FlagsEx`=0, `AllowableRaces`=64, `RewardXPDifficulty`=2, `RewardXPMultiplier`=1.0, `RewardNextQuest`=0, `StartItem`=0, `RewardSpell`=1277663, `TimeAllowed`=0, `VerifiedBuild`=70862, `QuestSortID`=-262, `RewardItem1`=0, `RewardAmount1`=0, `RewardItem2`=0, `RewardAmount2`=0, `RewardItem3`=0, `RewardAmount3`=0, `RewardItem4`=0, `RewardAmount4`=0, `RewardChoiceItemID1`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `RewardFactionID1`=0, `RewardFactionValue1`=0, `RewardFactionOverride1`=0, `RewardFactionID2`=0, `RewardFactionValue2`=0, `RewardFactionOverride2`=0, `RewardFactionID3`=0, `RewardFactionValue3`=0, `RewardFactionOverride3`=0, `RewardFactionID4`=0, `RewardFactionValue4`=0, `RewardFactionOverride4`=0, `RewardFactionID5`=0, `RewardFactionValue5`=0, `RewardFactionOverride5`=0 WHERE `ID`=94820 AND `VerifiedBuild`=-1;
