UPDATE `quest_template` SET `LogTitle`='Old Habits', `QuestDescription`='This book has been badly burned--perhaps by the dragonfire that destroyed much of the Dragonmaw clan.\n\nOf what little is legible, it seems to describe rituals relating to the use of the Demon Soul that the clan had used to control the dragons.\n\nIt is far too incomplete to be of real use, but based on roughly inserted pages on animal hide it seems Nek''rosh had attempted to salvage it. Freshly dried ink mentions a "Shadow Council."\n\nCaptain Stoutfist in Menethil Harbor would want to know about this.', `LogDescription`='Bring the Tattered Spellbook to Captain Stoutfist in Menethil Harbor.', `AreaDescription`='', `QuestCompletionLog`='', `Flags`=0, `FlagsEx`=0, `AllowableRaces`=6130900294268439629, `RewardXPDifficulty`=3, `RewardXPMultiplier`=1.0, `RewardNextQuest`=0, `StartItem`=280042, `RewardSpell`=0, `TimeAllowed`=0, `VerifiedBuild`=70862, `QuestSortID`=11, `RewardItem1`=0, `RewardAmount1`=0, `RewardItem2`=0, `RewardAmount2`=0, `RewardItem3`=0, `RewardAmount3`=0, `RewardItem4`=0, `RewardAmount4`=0, `RewardChoiceItemID1`=281306, `RewardChoiceItemQuantity1`=1, `RewardChoiceItemID2`=281307, `RewardChoiceItemQuantity2`=1, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `RewardFactionID1`=47, `RewardFactionValue1`=4, `RewardFactionOverride1`=0, `RewardFactionID2`=0, `RewardFactionValue2`=0, `RewardFactionOverride2`=0, `RewardFactionID3`=0, `RewardFactionValue3`=0, `RewardFactionOverride3`=0, `RewardFactionID4`=0, `RewardFactionValue4`=0, `RewardFactionOverride4`=0, `RewardFactionID5`=0, `RewardFactionValue5`=0, `RewardFactionOverride5`=0 WHERE `ID`=98223 AND `VerifiedBuild`=-1;
